  "prediction_basis_card_ids": ["C10", "C14", "C33", "C139", "C126", "C84", "C205"],
  "claims": [
    {
      "claim": "The most transferable gold contexts support F >= 20%: nilotinib has an assumed fasted absolute F of 31% (C10), and GSK1322322 has measured absolute F of 57-77% (C14, C33).",
      "card_ids": ["C10", "C14", "C33"]
    },
    {
      "claim": "L4 nilotinib Caco-2-derived human effective permeability (~1.5e-4 cm/s, C139) and L5 high-permeability/low-efflux anilinopyrimidine data (C205, C203) indicate the chemotype can be well absorbed despite solubility limitations.",
      "card_ids": ["C139", "C205", "C203"]
    },
    {
      "claim": "L3 alflutinib (close analog) shows measurable oral exposure after 80 mg (C126) and only a 1.23-fold Cmax increase with itraconazole (C84), suggesting a modest, not threshold-defeating, gut-wall/CYP3A or efflux contribution.",
      "card_ids": ["C126", "C84"]
    },
    {
      "claim": "L5 imatinib/tandutinib records demonstrate P-gp/BCRP efflux and increased oral availability when efflux is inhibited (C225, C209, C198, C220), but they do not quantify F and do not establish F < 20%; efflux substrate status alone is not affirmative threshold-relevant low evidence.",
      "card_ids": ["C225", "C209", "C198", "C220"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C225", "C209", "C198", "C220", "C179", "C202", "C214"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule.",
    "No query-specific or closest-analog (alflutinib) gut-wall efflux or intestinal metabolism measurement; L5 records are for imatinib, tandutinib, and other reference molecules.",
    "Nilotinib F of 31% is an assumed value, and its transfer to the query is uncertain because of structural differences (acrylamide/basic diamine vs amide/methylpiperazine).",
    "L3 alflutinib exposure lacks an IV comparator, so absolute F cannot be derived from it.",
    "Food, dose, formulation, and species differences between the query and the gold contexts are unmeasured.",
    "The query's low neutral fraction and likely efflux substrate status could reduce absorption, but no quantitative F impact is available."
  ],
  "decision_summary": "Predicted high (F >= 20%) is retained. The most transferable gold contexts (nilotinib 31% fasted; GSK1322322 57-77%) and L3 oral exposure for the close alflutinib analog support meaningful absorption; L4/L5 permeability records indicate the anilinopyrimidine TKI chemotype can be well absorbed. L5 imatinib/tandutinib efflux data are mechanistically contradictory but do not quantify F and do not establish F < 20%; the low physicochemical prior is not affirmative low evidence."
}

